module.exports = async function(data) {
  const input = data.validate_input || {};
  if (!input.inputValid) {
    return {
      verified: false,
      error: true,
      code: 'INVALID_SETUP_INTENT_INPUT',
      message: 'A valid setupIntentId is required.',
    };
  }
  const customerId = data.extract_customer_id && data.extract_customer_id.customerId;
  const si = data.get_setup_intent && data.get_setup_intent.data;
  if (!customerId) {
    return {
      verified: false,
      error: true,
      code: 'CUSTOMER_NOT_FOUND',
      message: 'No Stripe customer found for authenticated user.',
    };
  }
  if (!si || si.error || si.status !== 'succeeded') {
    return {
      verified: false,
      error: true,
      code: 'SETUP_INTENT_NOT_SUCCEEDED',
      status: (si && si.status) || null,
      message: (si && si.error && si.error.message) || 'Card setup has not succeeded.',
    };
  }
  const siCustomer = typeof si.customer === 'string' ? si.customer : (si.customer && si.customer.id);
  if (siCustomer !== customerId) {
    return {
      verified: false,
      error: true,
      code: 'SETUP_INTENT_CUSTOMER_MISMATCH',
      message: 'SetupIntent does not belong to the authenticated customer.',
    };
  }
  const pmObj = typeof si.payment_method === 'object' && si.payment_method !== null ? si.payment_method : null;
  const pmId = pmObj ? pmObj.id : (typeof si.payment_method === 'string' ? si.payment_method : null);
  if (!pmId || !pmId.startsWith('pm_')) {
    return {
      verified: false,
      error: true,
      code: 'PAYMENT_METHOD_MISSING',
      message: 'No payment method was attached to the SetupIntent.',
    };
  }
  const card = (pmObj && pmObj.card) || {};
  return {
    verified: true,
    setupIntentId: si.id,
    paymentMethodId: pmId,
    paymentMethod: pmObj ? {
      id: pmId,
      brand: card.brand || 'card',
      last4: card.last4 || '****',
      expMonth: card.exp_month || 0,
      expYear: card.exp_year || 0,
    } : undefined,
  };
};

