module.exports = async function(data) {
  const input = data.validate_input || {};
  if (!input.inputValid) {
    return {
      valid: false,
      code: 'INVALID_PAYMENT_METHOD_INPUT',
      message: 'A valid paymentMethodId is required.',
    };
  }
  const customerId = data.extract_customer && data.extract_customer.customerId;
  if (!customerId) {
    return {
      valid: false,
      code: 'CUSTOMER_NOT_FOUND',
      message: 'No Stripe customer found for authenticated user.',
    };
  }
  const pm = data.get_payment_method && data.get_payment_method.data;
  const pmCustomer = pm && (typeof pm.customer === 'string' ? pm.customer : (pm.customer && pm.customer.id));
  if (!pm || pm.error || pm.id !== input.paymentMethodId || pmCustomer !== customerId) {
    return {
      valid: false,
      code: 'PAYMENT_METHOD_OWNERSHIP_MISMATCH',
      message: 'Payment method does not belong to the authenticated customer.',
    };
  }
  const subsBody = data.get_active_subscriptions && data.get_active_subscriptions.data;
  const subs = (subsBody && Array.isArray(subsBody.data)) ? subsBody.data : [];
  let resolvedSubId = null;
  if (input.subscriptionId) {
    const matchingRequested = subs.find(function(s) {
      return s.id === input.subscriptionId && ['active', 'trialing', 'past_due'].includes(s.status);
    });
    if (!matchingRequested) {
      return {
        valid: false,
        code: 'SUBSCRIPTION_OWNERSHIP_MISMATCH',
        message: 'Specified subscription does not belong to the authenticated customer.',
      };
    }
    resolvedSubId = matchingRequested.id;
  } else {
    const activeSub = subs.find(function(s) {
      return ['active', 'trialing', 'past_due'].includes(s.status);
    });
    resolvedSubId = activeSub ? activeSub.id : null;
  }
  return {
    valid: true,
    customerId,
    paymentMethodId: input.paymentMethodId,
    subscriptionId: resolvedSubId,
  };
};

module.exports = async function(data) {
  const prep = data.verify_and_prepare || {};
  const custRes = data.update_customer_default && data.update_customer_default.data;
  const custDefault = custRes && custRes.invoice_settings && custRes.invoice_settings.default_payment_method;
  const custDefaultId = typeof custDefault === 'string' ? custDefault : (custDefault && custDefault.id);
  const customerUpdated = Boolean(custRes && !custRes.error && custDefaultId === prep.paymentMethodId);

  let subscriptionUpdated = true;
  if (prep.subscriptionId) {
    const subRes = data.update_subscription_default && data.update_subscription_default.data;
    const subDefault = subRes && subRes.default_payment_method;
    const subDefaultId = typeof subDefault === 'string' ? subDefault : (subDefault && subDefault.id);
    subscriptionUpdated = Boolean(subRes && !subRes.error && subDefaultId === prep.paymentMethodId);
  }

  if (!customerUpdated || !subscriptionUpdated) {
    return {
      updated: false,
      error: true,
      code: 'DEFAULT_UPDATE_INCOMPLETE',
      defaultPaymentMethodId: prep.paymentMethodId,
      customerDefaultUpdated: customerUpdated,
      subscriptionDefaultUpdated: subscriptionUpdated,
      subscriptionId: prep.subscriptionId,
      message: 'Could not verify default payment method update.',
    };
  }

  return {
    updated: true,
    defaultPaymentMethodId: prep.paymentMethodId,
    customerDefaultUpdated: customerUpdated,
    subscriptionDefaultUpdated: subscriptionUpdated,
    subscriptionId: prep.subscriptionId,
  };
};

