module.exports = async function(data) {
  const customerId = data.extract_customer_id && data.extract_customer_id.customerId;
  if (!customerId) {
    return {
      paymentMethods: [],
      defaultPaymentMethodId: null,
      customerDefaultPaymentMethodId: null,
      subscriptionDefaultPaymentMethodId: null,
      defaultVerified: true,
    };
  }

  const raw = data.get_payment_methods && data.get_payment_methods.data;
  const methods = (raw && Array.isArray(raw.data)) ? raw.data : [];

  const subRaw = data.get_active_subscription && data.get_active_subscription.data;
  const subs = (subRaw && Array.isArray(subRaw.data)) ? subRaw.data : [];
  const activeSub = subs.find(function(s) {
    return ['active', 'trialing', 'past_due'].includes(s.status);
  }) || null;
  const rawSubDefault = activeSub && activeSub.default_payment_method;
  const subDefault = typeof rawSubDefault === 'string'
    ? rawSubDefault
    : (rawSubDefault && rawSubDefault.id) || null;
  const custDefault = (data.extract_customer_id && data.extract_customer_id.customerDefaultPaymentMethodId) || null;
  const defaultPaymentMethodId = subDefault || custDefault || null;

  // Deduplicate by card fingerprint — keep the most recent PM per fingerprint,
  // or the active defaultPaymentMethodId if a duplicate fingerprint matches it.
  const seen = new Map();
  for (const pm of methods) {
    const fp = pm.card && pm.card.fingerprint;
    const key = fp || pm.id;
    if (!seen.has(key) || (defaultPaymentMethodId && pm.id === defaultPaymentMethodId)) {
      seen.set(key, pm);
    }
  }

  return {
    paymentMethods: Array.from(seen.values()).map(function(pm) {
      const isRenewalCard = Boolean(defaultPaymentMethodId && pm.id === defaultPaymentMethodId);
      return {
        id: pm.id,
        brand: pm.card.brand,
        last4: pm.card.last4,
        expMonth: pm.card.exp_month,
        expYear: pm.card.exp_year,
        isDefault: isRenewalCard,
        isRenewalCard: isRenewalCard,
      };
    }),
    defaultPaymentMethodId: defaultPaymentMethodId,
    customerDefaultPaymentMethodId: custDefault,
    subscriptionDefaultPaymentMethodId: subDefault,
    defaultVerified: true,
  };
};

