module.exports = async function(data) {
  const customerId = data.extract_customer_id && data.extract_customer_id.customerId;
  const custDefault = data.extract_customer_id && data.extract_customer_id.customerDefaultPaymentMethodId;
  const pmId = data.extract_email && data.extract_email.pmId;
  const validPm = data.extract_email && data.extract_email.validPm;
  if (!customerId || !validPm || !pmId) {
    return {
      allowed: false,
      error: true,
      code: 'INVALID_REQUEST',
      message: 'Valid customer and paymentMethodId are required.',
    };
  }
  const pm = data.get_payment_method && data.get_payment_method.data;
  const pmCustomer = pm && (typeof pm.customer === 'string' ? pm.customer : (pm.customer && pm.customer.id));
  if (!pm || pm.error || pm.id !== pmId || pmCustomer !== customerId) {
    return {
      allowed: false,
      error: true,
      code: 'PAYMENT_METHOD_OWNERSHIP_MISMATCH',
      message: 'Payment method does not belong to the authenticated customer.',
    };
  }
  const subRaw = data.get_active_subscription && data.get_active_subscription.data;
  const subs = (subRaw && Array.isArray(subRaw.data)) ? subRaw.data : [];
  const activeSub = subs.find(function(s) {
    return ['active', 'trialing', 'past_due'].includes(s.status);
  }) || null;
  if (activeSub) {
    const rawSubDefault = activeSub.default_payment_method;
    const subDefault = typeof rawSubDefault === 'string'
      ? rawSubDefault
      : (rawSubDefault && rawSubDefault.id) || null;
    const effectiveRenewalPm = subDefault || custDefault || null;
    if (effectiveRenewalPm === pmId) {
      return {
        allowed: false,
        error: true,
        code: 'RENEWAL_CARD_PROTECTED',
        message: 'Cannot remove the active subscription renewal card. Select another renewal card first.',
      };
    }
  }
  return {
    allowed: true,
    customerId,
    pmId,
  };
};

module.exports = async function(data) {
  const v = data.verify_ownership;
  if (!v || !v.allowed) {
    return {
      detached: false,
      error: true,
      code: (v && v.code) || 'DETACH_BLOCKED',
      message: (v && v.message) || 'Could not remove payment method.',
    };
  }
  const detached = data.detach_method && data.detach_method.data;
  if (!detached || detached.error || detached.id !== v.pmId) {
    return {
      detached: false,
      error: true,
      code: 'STRIPE_DETACH_FAILED',
      message: (detached && detached.error && detached.error.message) || 'Could not detach payment method.',
    };
  }
  return {
    detached: true,
    paymentMethodId: v.pmId,
  };
};
